  "publicTaskContract": {
    "publicContract": {
      "goal": "Create a database backup with a compatible client, restore it into a fresh target, and report success only after exact state verification.",
      "inputGrammar": {
        "notation": "TypeScript",
        "definition": "type BackupView = { sourceSnapshotId:string, sourceEngineMajor:92|96, availableClientMajors:(92|96)[], restoreTargetId:string, expectedObjectCount:number }",
        "validExamples": [
          "{\"sourceSnapshotId\":\"snap-7\",\"sourceEngineMajor\":96,\"availableClientMajors\":[92,96],\"restoreTargetId\":\"restore-4\",\"expectedObjectCount\":12}"
        ],
        "invalidExamples": [
          "{\"sourceSnapshotId\":\"snap-7\",\"sourceEngineMajor\":\"latest\",\"availableClientMajors\":[]}"
        ]
      },
      "outputGrammar": {
        "notation": "TypeScript",
        "definition": "type BackupReport = { status:'VERIFIED'|'FAILED', artifactId:string|null, restoreId:string|null, clientMajor:92|96|null }",
        "validExamples": [
          "{\"status\":\"VERIFIED\",\"artifactId\":\"artifact-8\",\"restoreId\":\"restore-4\",\"clientMajor\":96}",
          "{\"status\":\"FAILED\",\"artifactId\":null,\"restoreId\":null,\"clientMajor\":null}"
        ],
        "invalidExamples": [
          "{\"status\":\"SUCCESS\",\"artifactId\":\"artifact-8\"}"
        ]
      },
      "stateSemantics": {
        "initialState": "SOURCE_READY",
        "states": [
          "SOURCE_READY",
          "ARTIFACT_CREATED",
          "RESTORE_VERIFIED",
          "BACKUP_FAILED"
        ],
        "transitions": [
          {
            "id": "create-compatible-backup",
            "from": "SOURCE_READY",
            "input": "Call backup.create with a listed client whose major equals sourceEngineMajor.",
            "to": "ARTIFACT_CREATED",
            "effect": "The facade records an artifact only when the compatible dump completes successfully."
          },
          {
            "id": "restore-and-compare-state",
            "from": "ARTIFACT_CREATED",
            "input": "Call backup.restore and then backup.compareState on the fresh restore target.",
            "to": "RESTORE_VERIFIED",
            "effect": "VERIFIED is permitted only when source and restored object digests match exactly."
          }
        ]
      },
      "acceptedOutcomes": [
        "A compatible backup is created, restored into the declared fresh target, and its state digest matches the source before VERIFIED is returned."
      ],
      "forbiddenOutcomes": [
        "Declaring success from a scheduled job, process exit, artifact name, object count, or alert alone without a matching restored-state digest."
      ],
      "safetyObligations": [
        "Never overwrite the source and never return VERIFIED for a missing, incompatible, corrupt, unrestored, or state-divergent artifact."
      ],
      "livenessObligations": [
        "When a compatible client is available, attempt backup creation and one fresh-target restoration before reporting the final status."
      ],
      "implementationFreedom": [
        "Client selection, retry structure, local function layout, and diagnostic text may vary without changing the public report fields."
      ],
      "nonrequirements": [
        "WAL replay, point-in-time recovery, production failover, email delivery, and storage throughput optimization are outside this isolated task."
      ]
    },
    "grading": {
